style.css:
/* ==========================================================================
   Claude.ai 핑크 테마 (Userstyle)
   
   사용법:
   1. Chrome/Edge/Firefox에 "Stylus" 확장 프로그램을 설치하세요.
   2. Stylus 아이콘 클릭 → "새 스타일 작성" → 아래 코드를 붙여넣기
   3. 적용 대상(Applies to)을 "claude.ai" 도메인으로 설정 후 저장
   
   ※ claude.ai는 Anthropic이 수시로 업데이트하므로, 클래스명이 바뀌면
     일부 스타일이 깨질 수 있습니다. 그럴 경우 개발자 도구(F12)로
     실제 클래스명을 확인해 선택자를 수정해 주세요.
   ========================================================================== */

/* ---------- 색상 변수 정의 ---------- */
:root {
  --pink-50:  #fff0f6;
  --pink-100: #ffd6e8;
  --pink-200: #ffadd2;
  --pink-300: #ff85c0;
  --pink-400: #f759ab;
  --pink-500: #eb2f96;
  --pink-600: #c41d7f;
  --pink-700: #9e1068;
  --pink-accent: #ff4da6;
  --pink-bg: #fff5f9;
  --pink-surface: #ffe4f0;
  --pink-text: #4a1030;
}

/* ---------- 전체 배경 ---------- */
html, body,
[class*="bg-bg-100"],
[class*="bg-bg-000"] {
  background-color: var(--pink-bg) !important;
}

/* ---------- 사이드바 ---------- */
nav,
[class*="sidebar"],
aside {
  background-color: var(--pink-surface) !important;
  border-color: var(--pink-200) !important;
}

/* ---------- 메인 채팅 영역 배경 ---------- */
main,
[class*="chat"],
[class*="conversation"] {
  background-color: var(--pink-bg) !important;
}

/* ---------- 메시지 말풍선 (사용자) ---------- */
[data-testid="user-message"],
[class*="human-message"],
[class*="user-turn"] {
  background-color: var(--pink-300) !important;
  color: #fff !important;
  border-radius: 16px !important;
}

/* ---------- 메시지 말풍선 (Claude 응답) ---------- */
[data-testid="assistant-message"],
[class*="assistant-message"],
[class*="model-turn"] {
  background-color: #ffffff !important;
  border: 1px solid var(--pink-200) !important;
  border-radius: 16px !important;
  color: var(--pink-text) !important;
}

/* ---------- 버튼 ---------- */
button {
  transition: background-color 0.15s ease, color 0.15s ease;
}

button[class*="primary"],
button[data-testid*="send"] {
  background-color: var(--pink-500) !important;
  color: #fff !important;
  border-color: var(--pink-500) !important;
}

button[class*="primary"]:hover,
button[data-testid*="send"]:hover {
  background-color: var(--pink-600) !important;
}

/* ---------- 링크 & 강조 텍스트 ---------- */
a, a:visited {
  color: var(--pink-600) !important;
}

::selection {
  background-color: var(--pink-200);
  color: var(--pink-700);
}

/* ---------- 입력창 ---------- */
textarea,
[contenteditable="true"],
[class*="input"] {
  background-color: #ffffff !important;
  border: 1.5px solid var(--pink-300) !important;
  border-radius: 12px !important;
  color: var(--pink-text) !important;
}

textarea:focus,
[contenteditable="true"]:focus {
  border-color: var(--pink-accent) !important;
  box-shadow: 0 0 0 2px var(--pink-100) !important;
}

/* ---------- 스크롤바 (웹킷 기반 브라우저) ---------- */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: var(--pink-50);
}

::-webkit-scrollbar-thumb {
  background: var(--pink-300);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--pink-400);
}

/* ---------- 코드 블록 ---------- */
pre, code {
  background-color: var(--pink-50) !important;
  border: 1px solid var(--pink-200) !important;
  border-radius: 8px !important;
}

/* ---------- 카드 / 아티팩트 패널 ---------- */
[class*="artifact"],
[class*="card"] {
  background-color: #ffffff !important;
  border: 1px solid var(--pink-200) !important;
}

/* ---------- 아바타 / 프로필 아이콘 강조 ---------- */
[class*="avatar"] {
  outline: 2px solid var(--pink-accent) !important;
  outline-offset: 1px;
}
